window.docContents[144].resolve({"/Parabolic-Equations/Coverage-and-Open-Problems/#PDEAtlas--Parabolic-Equations--Coverage-and-Open-Problems":{"contents":"\n\n","context":"PDEAtlas\u0009Parabolic Equations","header":"6.8. Coverage and Open Problems","id":"/Parabolic-Equations/Coverage-and-Open-Problems/#PDEAtlas--Parabolic-Equations--Coverage-and-Open-Problems"},"/Parabolic-Equations/Diffusion-and-weak-evolution/#PDEAtlas--Parabolic-Equations--Diffusion-and-weak-evolution--Positive-time-and-the-initial-instant":{"contents":"Smoothing holds at positive time, while convergence to the initial datum\nmay take place in a weaker norm. With rough coefficients, the time\nderivative may exist only in a dual space.\n\nInitial data cannot be swapped for an arbitrary time trace, and estimates that\nhold almost everywhere in time need not hold at the initial instant. Each\npassage to  needs a continuity or limiting theorem of its own.\n\n","context":"PDEAtlas\u0009Parabolic Equations\u0009Diffusion and weak evolution","header":"6.1.1. Positive time and the initial instant","id":"/Parabolic-Equations/Diffusion-and-weak-evolution/#PDEAtlas--Parabolic-Equations--Diffusion-and-weak-evolution--Positive-time-and-the-initial-instant"}});